param(
  [ValidateSet('x86', 'x64')][string]$CompileArchitecture,
  [string]$SourcePath,
  [string]$CompilerPath
)
$ErrorActionPreference = 'Stop'
$repoRoot = Split-Path $PSScriptRoot -Parent
if (!$SourcePath) { $SourcePath = Join-Path $repoRoot '.deps/dxvk-remix' }
$source = (Resolve-Path -LiteralPath $SourcePath).Path
if (!$CompileArchitecture) {
  foreach ($arch in @('x86', 'x64')) {
    $arguments = @('-NoProfile', '-File', $PSCommandPath, '-CompileArchitecture', $arch, '-SourcePath', $source)
    if ($CompilerPath) { $arguments += @('-CompilerPath', $CompilerPath) }
    & powershell.exe @arguments
    if ($LASTEXITCODE -ne 0) { throw "Host float constant cache test failed for $arch" }
  }
  exit 0
}
$output = Join-Path $repoRoot ".deps/constant-cache-test-$CompileArchitecture"
New-Item -ItemType Directory -Force $output | Out-Null
$hostSource = Get-Content -Raw (Join-Path $source 'bridge/src/server/main.cpp')
$helper = [regex]::Match($hostSource, '(?s)template<typename Device, typename Backend>\r?\nstatic auto setHostFloatConstants.*?\r?\n}\r?\n(?=// NV-DXVK end: Float constant backend cache\.)')
if (!$helper.Success) { throw 'Actual Host float constant helper was not found' }
$cases = foreach ($command in @('SetVertexShaderConstantF', 'SetPixelShaderConstantF')) {
  $case = [regex]::Match($hostSource, "(?ms)^      case IDirect3DDevice9Ex_${command}:\r?\n      \{.*?^      \}\r?\n")
  if (!$case.Success) { throw "Actual Host $command case was not found" }
  $case.Value
}
[IO.File]::WriteAllText((Join-Path $output 'constant_cache_host_set.inc'), $helper.Value)
[IO.File]::WriteAllText((Join-Path $output 'constant_cache_host_cases.inc'), ($cases -join "`n"))

if (!$CompilerPath) {
  if (Get-Command cl.exe -ErrorAction SilentlyContinue) { $CompilerPath = 'cl.exe' }
  else {
    $portableName = if ($CompileArchitecture -eq 'x86') { 'i686-w64-mingw32-g++.exe' } else { 'g++.exe' }
    $portable = Join-Path $repoRoot ".deps/compact-tools/toolchain/w64devkit/bin/$portableName"
    if (Test-Path -LiteralPath $portable) { $CompilerPath = $portable }
    else { $CompilerPath = 'cl.exe' }
  }
}
if ([IO.Path]::GetFileName($CompilerPath) -eq 'cl.exe') {
  . (Join-Path $source 'bridge/build_common.ps1')
  SetupVS -Platform $CompileArchitecture -VcVarsVer '14.29'
}
$executable = Join-Path $output 'constant-cache.exe'
Push-Location $output
try {
  if ([IO.Path]::GetFileName($CompilerPath) -eq 'cl.exe') {
    & $CompilerPath /nologo /std:c++17 /EHsc /W4 /WX "/I$source/bridge/src/server" "/I$output" "$repoRoot/tests/constant_cache.cpp" "/Fe:$executable"
  } else {
    $machine = if ($CompileArchitecture -eq 'x86') { '-m32' } else { '-m64' }
    & $CompilerPath $machine -std=c++17 -O2 -Wall -Wextra -Werror -static "-I$source/bridge/src/server" "-I$output" "$repoRoot/tests/constant_cache.cpp" -o $executable
  }
  if ($LASTEXITCODE -ne 0) { throw 'Host float constant cache compilation failed' }
  & $executable
  if ($LASTEXITCODE -ne 0) { throw 'Host float constant cache regression failed' }
} finally { Pop-Location }
